const clubs=[['BUF','Buffalo','Bills','AFC East'],['MIA','Miami','Dolphins','AFC East'],['NE','New England','Patriots','AFC East'],['NYJ','New York','Jets','AFC East'],['BAL','Baltimore','Ravens','AFC North'],['CIN','Cincinnati','Bengals','AFC North'],['CLE','Cleveland','Browns','AFC North'],['PIT','Pittsburgh','Steelers','AFC North'],['HOU','Houston','Texans','AFC South'],['IND','Indianapolis','Colts','AFC South'],['JAX','Jacksonville','Jaguars','AFC South'],['TEN','Tennessee','Titans','AFC South'],['DEN','Denver','Broncos','AFC West'],['KC','Kansas City','Chiefs','AFC West'],['LV','Las Vegas','Raiders','AFC West'],['LAC','Los Angeles','Chargers','AFC West'],['DAL','Dallas','Cowboys','NFC East'],['NYG','New York','Giants','NFC East'],['PHI','Philadelphia','Eagles','NFC East'],['WAS','Washington','Commanders','NFC East'],['CHI','Chicago','Bears','NFC North'],['DET','Detroit','Lions','NFC North'],['GB','Green Bay','Packers','NFC North'],['MIN','Minnesota','Vikings','NFC North'],['ATL','Atlanta','Falcons','NFC South'],['CAR','Carolina','Panthers','NFC South'],['NO','New Orleans','Saints','NFC South'],['TB','Tampa Bay','Buccaneers','NFC South'],['ARI','Arizona','Cardinals','NFC West'],['LAR','Los Angeles','Rams','NFC West'],['SF','San Francisco','49ers','NFC West'],['SEA','Seattle','Seahawks','NFC West']];
const positions=['QB','RB','WR','WR','TE','OL','OL','OL','OL','OL','DL','DL','DL','LB','LB','LB','CB','CB','S','S','K'];
const first=['Marcus','Caleb','Jordan','Isaiah','Devin','Ethan','Malik','Noah','Jalen','Cameron','Darius','Miles','Tyler','Xavier','Andre','Cole','Elijah','Trey','Logan','Zion'];const last=['Mitchell','Hayes','Carter','Brooks','Washington','Reed','Walker','Collins','Bennett','Marshall','Porter','Davis','Grant','Williams','Anderson','Coleman','Foster','Sullivan','Jackson','Robinson'];
let state,view='Overview',filter='All',search='',league='NFC East';let seed=42;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}function ri(a,b){return Math.floor(rand()*(b-a+1))+a}function player(i,rookie=false){let o=ri(62,91);return{id:'p'+i,name:first[ri(0,19)]+' '+last[ri(0,19)],pos:positions[i%21],ovr:o,pot:Math.min(99,o+ri(2,12)),age:rookie?ri(21,23):ri(23,33),salary:rookie?ri(10,30)/10:Math.round((o-55)*(positions[i%21]==='QB'?0.65:0.22)*10)/10,starter:i<21,injury:0}}
function schedule(){let ring=Array.from({length:32},(_,i)=>i),weeks=[];for(let w=0;w<17;w++){let games=[];for(let i=0;i<16;i++)games.push({a:ring[i],b:ring[31-i],score:null});weeks.push(games);ring.splice(1,0,ring.pop())}return weeks}
function fresh(team=16,year=2026,roster=null){seed=42+year;let s={team,year,week:0,teams:clubs.map((c,i)=>({w:0,l:0,pf:0,pa:0,rating:ri(71,88)})),schedule:schedule(),roster:roster||Array.from({length:32},(_,i)=>player(i)),agents:Array.from({length:18},(_,i)=>({...player(100+i),id:`fa-${year}-${i}`,starter:false})),prospects:Array.from({length:24},(_,i)=>({...player(200+i,true),id:`draft-${year}-${i}`,starter:false})),plan:{offense:'Balanced',defense:'Zone coverage',training:'Balanced'},news:[],morale:78,drafted:0,phase:'season',playoffs:null,history:[]};s.news=[{title:'Your era starts here',body:'The board wants a winning season. Build your roster, set the game plan, and make your mark.',week:0},{title:'Scouting department ready',body:'Your first draft class is available to scout. Three picks await in the offseason.',week:0},{title:'Room to build',body:'Free agency is open. Find a difference-maker while staying under the $255M salary cap.',week:0}];return s}
try{state=globalThis.__gridironLoadedState||JSON.parse(localStorage.getItem('gridiron-v1'))}catch{}if(!state||!state.schedule)state=fresh();league=clubs[state.team][3];function save(){if(globalThis.careerStore)return;try{localStorage.setItem('gridiron-v1',JSON.stringify(state))}catch{document.querySelector('.save').textContent='Storage unavailable'}}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',3000)}function news(title,body){state.news.unshift({title,body,week:state.week})}function money(){return state.roster.reduce((s,p)=>s+p.salary,0)}function rating(){let starters=state.roster.filter(p=>p.starter);return Math.round(starters.reduce((s,p)=>s+p.ovr-(p.injury?15:0),0)/Math.max(1,starters.length))}function rec(i){let t=state.teams[i];return t.w+'–'+t.l}function cname(i){return clubs[i][1]+' '+clubs[i][2]}function game(){return state.phase==='season'?state.schedule[state.week]?.find(g=>g.a===state.team||g.b===state.team):state.phase==='playoffs'?state.playoffs.rounds.at(-1).find(g=>g.a===state.team||g.b===state.team):null}function opponent(){let g=game();return g?(g.a===state.team?g.b:g.a):null}function rank(ids){return ids.sort((a,b)=>state.teams[b].w-state.teams[a].w||(state.teams[b].pf-state.teams[b].pa)-(state.teams[a].pf-state.teams[a].pa))}function phaseName(){return state.phase==='season'?'Week '+(state.week+1)+' / 17':state.phase==='playoffs'?['Divisional round','Conference final','Championship'][state.playoffs.rounds.length-1]:'Offseason'}function actionLabel(){return state.phase==='offseason'?'Begin next season →':state.phase==='playoffs'?'Simulate playoff round →':'Play week '+(state.week+1)+' →'}
const navs=[['Overview','◫'],['Roster','♙'],['Game plan','⌘'],['Schedule','▦'],['League','◉'],['Free agency','⇄'],['Draft','◇']];function go(v){view=v;filter='All';search='';render()}function render(){save();document.getElementById('nav').innerHTML=navs.map(([n,i])=>`<button class="${view===n?'active':''}" onclick="go('${n}')"><span>${i}</span>${n}</button>`).join('');document.getElementById('club').innerHTML=`<div class="clubbox"><div class="shield">${clubs[state.team][0]}</div><div>${clubs[state.team][2]}<small>${clubs[state.team][3]} · ${state.year}</small></div></div>`;document.getElementById('breadcrumb').textContent='FRONT OFFICE / '+view.toUpperCase();let subtitle={Overview:'Every decision builds a dynasty.',Roster:'Build the team that brings it home.','Game plan':'Your identity. Your playbook. Your advantage.',Schedule:'The road to the championship.',League:'Keep an eye on the competition.','Free agency':'Find your next difference-maker.',Draft:'The future of your franchise starts here.'}[view];document.getElementById('app').innerHTML=`<div class="title-row"><div><div class="eyebrow">${state.year} SEASON · ${clubs[state.team][1]}</div><h1>${view==='Overview'?'The front office':view}</h1><p class="subtitle">${subtitle}</p></div><div class="title-actions"><span class="week">${phaseName()}</span><button onclick="advance()">${actionLabel()}</button></div></div>${({Overview:overview,Roster:roster,'Game plan':plan,Schedule:calendar,League:standings,'Free agency':agency,Draft:draft}[view])()}`}
function overview(){let o=opponent(),r=rating(),standing=rank(clubs.map((_,i)=>i).filter(i=>clubs[i][3]===clubs[state.team][3])).indexOf(state.team)+1;return `<div class="grid"><div><div class="panel hero"><div class="eyebrow">${state.phase==='offseason'?'THE NEXT CHAPTER':o===null?'POSTSEASON WATCH':'NEXT UP · '+phaseName()}</div>${o!==null?`<div class="matchup"><div><div class="crest">${clubs[state.team][0]}</div><div class="teamname">${clubs[state.team][2]}</div><div class="record">${rec(state.team)} · OVR ${r}</div></div><div class="versus">VS</div><div><div class="crest" style="background:#65483a">${clubs[o][0]}</div><div class="teamname">${clubs[o][2]}</div><div class="record">${rec(o)} · OVR ${state.teams[o].rating}</div></div></div><div class="match-info">${game().a===state.team?'HOME FIELD':'ON THE ROAD'} &nbsp; / &nbsp; ${cname(game().a).toUpperCase()}</div>`:`<h1 style="margin:26px 0">${state.phase==='offseason'?'Build your next contender.':'The stakes just got higher.'}</h1><p class="subtitle">${state.phase==='offseason'?'Make your draft picks and prepare for a new season.':'Your franchise is out. Simulate the remaining playoff rounds.'}</p>`}<div class="hero-bottom"><span>GAME PLAN <b style="color:var(--lime);margin-left:12px">${state.plan.offense}</b></span><button class="link" onclick="go('Game plan')">Edit game plan ↗</button></div></div><div class="stats"><div class="stat"><div class="label">SEASON RECORD</div><b>${rec(state.team)}</b><small>#${standing} in ${clubs[state.team][3]}</small></div><div class="stat"><div class="label">TEAM RATING</div><b>${r}<span style="font-size:15px;color:var(--muted)"> / 99</span></b><small>Active starters</small></div><div class="stat"><div class="label">CAP SPACE</div><b>$${(255-money()).toFixed(1)}<span style="font-size:15px">M</span></b><small>$255M salary cap</small></div><div class="stat"><div class="label">TEAM MORALE</div><b class="positive">${state.morale}%</b><small>${state.morale>65?'Ready to compete':'Needs a lift'}</small></div></div><div class="panel"><div class="panel-head"><h2>Inside the franchise</h2><span class="label">LATEST UPDATES</span></div>${state.news.slice(0,4).map((n,i)=>`<div class="news-item"><div class="news-icon">${['↗','◇','≡','+'][i]}</div><div><h3>${n.title}</h3><p>${n.body}</p><small>${n.week?'After week '+n.week:'Front office briefing'}</small></div></div>`).join('')}</div></div><div><div class="panel"><div class="panel-head"><h2>Board confidence</h2><span class="tag green">${state.teams[state.team].w>=state.teams[state.team].l?'ON TRACK':'UNDER REVIEW'}</span></div><div class="pad"><p style="font-size:12px;color:var(--muted);line-height:1.7">“Build a contender. Give this city a reason to believe.”</p><div class="kv"><span>Season objective</span><b>Win 9 games</b></div><div class="meter"><i style="width:${Math.min(100,state.teams[state.team].w/9*100)}%"></i></div><div class="kv"><span>Financial discipline</span><b class="positive">Under the cap</b></div><div class="kv"><span>Roster availability</span><b>${state.roster.filter(p=>!p.injury).length} / ${state.roster.length}</b></div></div></div><div class="panel section-gap"><div class="panel-head"><h2>On the practice field</h2><span class="tag">OFFENSE</span></div><div class="pad"><div style="display:flex;justify-content:space-between"><b>${state.plan.offense}</b><span class="label">11 PERSONNEL</span></div>${field()}<div class="kv"><span>Weekly focus</span><b>${state.plan.training}</b></div><div class="kv"><span>Defensive scheme</span><b>${state.plan.defense}</b></div><button class="secondary small" style="width:100%;margin-top:22px" onclick="go('Game plan')">Open the playbook ↗</button></div></div><button class="link" style="margin-top:20px;color:var(--muted)" onclick="chooseClub()">Start a new career ↗</button></div></div>`}
function field(){return `<div class="field">${[['WR',10,35],['WR',90,35],['TE',78,40],['OL',35,45],['OL',43,45],['C',51,45],['OL',59,45],['OL',67,45],['QB',51,63],['RB',38,78],['WR',18,60]].map(([p,x,y])=>`<span class="player-dot" style="left:${x}%;top:${y}%">${p}</span>`).join('')}</div>`}
function filters(){return `<div class="tabs">${['All','Offense','Defense','Special teams'].map(t=>`<button class="${filter===t?'active':''}" onclick="filter='${t}';render()">${t}</button>`).join('')}</div>`}function filtered(players){return players.filter(p=>filter==='All'||(filter==='Offense'?['QB','RB','WR','TE','OL'].includes(p.pos):filter==='Defense'?['DL','LB','CB','S'].includes(p.pos):p.pos==='K'))}function ptable(ps,mode){return `<div class="scroll"><table><thead><tr><th>PLAYER</th><th>POS</th><th>AGE</th><th>OVR</th><th>POT</th><th>${mode==='draft'?'ROOKIE DEAL':'SALARY'}</th><th>STATUS / ACTION</th></tr></thead><tbody>${ps.map(p=>`<tr><td><b>${p.name}</b><small>${p.injury?'Injured · '+p.injury+' week(s)':mode==='draft'?'College prospect':p.age<26?'Young talent':'Veteran presence'}</small></td><td><span class="tag">${p.pos}</span></td><td>${p.age}</td><td><span class="rating">${p.ovr}</span></td><td>${p.pot}</td><td>$${p.salary.toFixed(1)}M</td><td>${mode==='roster'?`<button class="small ${p.starter?'':'secondary'}" onclick="toggleStarter('${p.id}')">${p.starter?'Starter':'Reserve'}</button> <button class="link" onclick="releasePlayer('${p.id}')" style="margin-left:8px;color:#f49b85">Release</button>`:mode==='draft'?`<button class="small" onclick="draftPlayer('${p.id}')" ${state.phase!=='offseason'||state.drafted>=3?'disabled':''}>Draft</button>`:`<button class="small" onclick="signPlayer('${p.id}')" ${money()+p.salary>255||state.roster.length>=53?'disabled':''}>Sign player +</button>`}</td></tr>`).join('')||'<tr><td colspan="7">No players in this group.</td></tr>'}</tbody></table></div>`}function roster(){return `${filters()}<div class="panel"><div class="panel-head"><h2>First team & depth chart</h2><span class="label">${state.roster.length} / 53 PLAYERS · $${money().toFixed(1)}M COMMITTED</span></div>${ptable(filtered(state.roster),'roster')}</div><p class="subtitle">Select a reserve to replace the lowest-rated starter at that position. Releases have no dead-cap penalty in this simulation.</p>`}function toggleStarter(id){let p=state.roster.find(p=>p.id===id);if(p.starter){toast('Choose a reserve at this position to replace a starter.');return}let same=state.roster.filter(q=>q.pos===p.pos&&q.starter).sort((a,b)=>a.ovr-b.ovr);if(same.length)same[0].starter=false;p.starter=true;render();toast(p.name+' promoted to starter')}function releasePlayer(id){let p=state.roster.find(p=>p.id===id);if(p.starter){toast('Replace this starter before releasing him.');return}modal(`<h2>Release ${p.name}?</h2><p>This frees $${p.salary.toFixed(1)}M of cap space. He will enter the free-agent pool.</p><div class="modal-actions"><button class="secondary" onclick="closeModal()">Keep player</button><button onclick="confirmRelease('${id}')">Release player</button></div>`)}function confirmRelease(id){let p=state.roster.find(p=>p.id===id);state.roster=state.roster.filter(p=>p.id!==id);state.agents.push(p);closeModal();news('Roster move',p.name+' has been released.');render()}function agency(){return `<div class="stats"><div class="stat"><div class="label">AVAILABLE CAP</div><b>$${(255-money()).toFixed(1)}M</b><small>Simulation cap: $255M</small></div><div class="stat"><div class="label">ROSTER SPOTS</div><b>${53-state.roster.length}</b><small>Maximum 53 players</small></div></div>${filters()}<div class="panel"><div class="panel-head"><h2>Available free agents</h2><span class="label">SIMULATED PLAYER MARKET</span></div>${ptable(filtered(state.agents).sort((a,b)=>b.ovr-a.ovr),'agent')}</div>`}function signPlayer(id){let p=state.agents.find(p=>p.id===id);if(!p||money()+p.salary>255||state.roster.length>=53)return;state.agents=state.agents.filter(p=>p.id!==id);state.roster.push({...p,starter:false});news('A new face in the building',p.name+' ('+p.pos+') signed for $'+p.salary.toFixed(1)+'M per season.');render();toast(p.name+' signed. Set his role in Roster.')}
function plan(){return `<div class="two"><div class="panel"><div class="panel-head"><h2>Your weekly game plan</h2><span class="tag green">APPLIES NEXT GAME</span></div><div class="pad">${[['offense','Offensive identity',['Balanced','Air raid','Ground control'],'Balanced reduces volatility. Air raid benefits elite QBs and receivers. Ground control benefits strong running backs and linemen.'],['defense','Defensive approach',['Zone coverage','Man coverage','Aggressive blitz'],'Zone is consistent. Man coverage rewards talented defensive backs. Blitz raises both sack potential and big-play risk.'],['training','Training intensity',['Balanced','Development','Recovery'],'Development can improve players but increases injury risk. Recovery clears an extra injury week. Balanced provides steady preparation.']].map(([key,label,opts,desc])=>`<div class="form-row"><label>${label}</label><select onchange="setPlan('${key}',this.value)">${opts.map(o=>`<option ${state.plan[key]===o?'selected':''}>${o}</option>`).join('')}</select><small>${desc}</small></div>`).join('')}<p class="subtitle">Changes save automatically. Team strength, personnel fit, morale, home field, and chance all influence results.</p></div></div><div class="panel"><div class="panel-head"><h2>Offensive personnel</h2><span class="label">SCHEMATIC VIEW</span></div><div class="pad">${field()}${state.roster.filter(p=>p.starter&&['QB','RB','WR','TE'].includes(p.pos)).map(p=>`<div class="kv"><span>${p.pos} · ${p.name}</span><b class="positive">${p.ovr}</b></div>`).join('')}</div></div></div>`}function setPlan(k,v){state.plan[k]=v;save();toast('Game plan updated')}
function calendar(){return `<div class="panel"><div class="panel-head"><h2>${state.year} regular season</h2><span class="label">17 GAMES · SIMPLIFIED SCHEDULE</span></div><div class="scroll"><table><thead><tr><th>WEEK</th><th>OPPONENT</th><th>VENUE</th><th>RESULT</th></tr></thead><tbody>${state.schedule.map((gs,w)=>{let g=gs.find(g=>g.a===state.team||g.b===state.team),home=g.a===state.team,o=home?g.b:g.a,score=g.score;return `<tr class="${w===state.week?'me':''}"><td>${String(w+1).padStart(2,'0')}</td><td><b>${cname(o)}</b><small>${clubs[o][3]}</small></td><td>${home?'Home':'Away'}</td><td>${score?`<b class="${score[home?0:1]>score[home?1:0]?'positive':'negative'}">${score[home?0:1]>score[home?1:0]?'W':'L'} ${score[home?0:1]} – ${score[home?1:0]}</b>`:'<span class="tag">'+(w===state.week?'UP NEXT':'SCHEDULED')+'</span>'}</td></tr>`}).join('')}</tbody></table></div></div>${state.playoffs?`<div class="panel section-gap"><div class="panel-head"><h2>Playoff bracket</h2><span class="label">TOP 4 PER CONFERENCE</span></div>${state.playoffs.rounds.map((gs,r)=>`<div class="pad"><h3>${['Divisional round','Conference finals','Championship'][r]}</h3>${gs.map(g=>`<div class="kv"><span>${clubs[g.a][0]} vs ${clubs[g.b][0]}</span><b>${g.score?g.score.join(' – '):'Upcoming'}</b></div>`).join('')}</div>`).join('')}</div>`:''}`}
function standings(){let ids=rank(clubs.map((_,i)=>i).filter(i=>league==='All'||clubs[i][3]===league));return `<div class="tabs"><select style="width:240px" onchange="league=this.value;render()">${['All',...new Set(clubs.map(c=>c[3]))].map(d=>`<option ${league===d?'selected':''}>${d}</option>`).join('')}</select></div><div class="panel"><div class="panel-head"><h2>League standings</h2><span class="label">TIEBREAKER: POINT DIFFERENTIAL</span></div><div class="scroll"><table><thead><tr><th>#</th><th>FRANCHISE</th><th>W</th><th>L</th><th>PF</th><th>PA</th><th>DIFF</th></tr></thead><tbody>${ids.map((i,n)=>{let t=state.teams[i];return `<tr class="${i===state.team?'me':''}"><td>${n+1}</td><td><b>${cname(i)} ${i===state.team?'<span class="tag green">YOU</span>':''}</b><small>${clubs[i][3]}</small></td><td>${t.w}</td><td>${t.l}</td><td>${t.pf}</td><td>${t.pa}</td><td class="${t.pf>=t.pa?'positive':'negative'}">${t.pf-t.pa>0?'+':''}${t.pf-t.pa}</td></tr>`}).join('')}</tbody></table></div></div><p class="subtitle">Top four teams in each conference qualify for a simplified eight-team playoff. Division titles do not guarantee qualification.</p>`}
function draft(){return `<div class="panel" style="margin-bottom:20px"><div class="pad"><div class="eyebrow">${state.year+1} DRAFT CLASS</div><h2 style="margin-top:10px">Build for the long run.</h2><p class="subtitle">${state.phase==='offseason'?'You are on the clock. Select up to three prospects before beginning the next season.':'Scout now. Make three selections once the championship is complete.'}</p><div class="kv"><span>Selections remaining</span><b>${3-state.drafted} / 3</b></div></div></div>${filters()}<div class="panel">${ptable(filtered(state.prospects).sort((a,b)=>b.pot-a.pot),'draft')}</div><p class="subtitle">Simplified draft: three uncontested picks from a shared prospect board; rookie salaries count against your cap.</p>`}function draftPlayer(id){if(state.phase!=='offseason'||state.drafted>=3)return;let p=state.prospects.find(p=>p.id===id);if(money()+p.salary>255||state.roster.length>=53){toast('Free roster space and salary cap before drafting.');return}state.prospects=state.prospects.filter(p=>p.id!==id);state.roster.push(p);state.drafted++;news('The next generation',p.name+' joins the franchise with selection '+state.drafted+'.');render();toast(p.name+' drafted!')}
function strength(i){if(i!==state.team)return state.teams[i].rating;let group=state.roster.filter(p=>p.starter&&!p.injury);let key=state.plan.offense==='Air raid'?['QB','WR']:state.plan.offense==='Ground control'?['RB','OL']:[];let fit=key.length?group.filter(p=>key.includes(p.pos)).reduce((s,p)=>s+(p.ovr-75),0)/Math.max(1,group.filter(p=>key.includes(p.pos)).length)*.35:1;let db=group.filter(p=>['CB','S'].includes(p.pos));return rating()+fit+(state.morale-70)*.06+(state.plan.defense==='Man coverage'?db.reduce((s,p)=>s+p.ovr-75,0)/Math.max(1,db.length)*.15:0)}
function simulate(g,regular){let a=strength(g.a),b=strength(g.b),risk=(g.a===state.team||g.b===state.team)&&(state.plan.offense==='Air raid'||state.plan.defense==='Aggressive blitz')?5:0;let scores=[Math.max(3,Math.round(23+(a-b)*.5+2+(rand()-.5)*(28+risk))),Math.max(3,Math.round(23+(b-a)*.5+(rand()-.5)*(28+risk)))];if(scores[0]===scores[1])scores[ri(0,1)]+=3;g.score=scores;if(regular){[g.a,g.b].forEach((i,k)=>{let t=state.teams[i];t.pf+=scores[k];t.pa+=scores[1-k];t[scores[k]>scores[1-k]?'w':'l']++})}return scores[0]>scores[1]?g.a:g.b}
function advance(){if(state.phase==='offseason'){modal(`<h2>A new season awaits.</h2><p>You have ${3-state.drafted} unused draft picks. Starting a new season keeps your roster, ages players, develops young talent, and resets standings. Unused picks expire.</p><div class="modal-actions"><button class="secondary" onclick="closeModal();go('Draft')">Visit draft</button><button onclick="nextSeason()">Start ${state.year+1} season</button></div>`);return}seed=Date.now()>>>0;let own=game(),gs=state.phase==='season'?state.schedule[state.week]:state.playoffs.rounds.at(-1);let regular=state.phase==='season';gs.forEach(g=>simulate(g,regular));let report=own?{...own,score:[...own.score]}:null;if(regular){state.week++;state.roster.forEach(p=>{p.injury=Math.max(0,p.injury-(state.plan.training==='Recovery'?2:1));if(state.plan.training==='Development'&&p.age<28&&rand()<.2)p.ovr=Math.min(p.pot,p.ovr+1)});if(rand()<(state.plan.training==='Development'?.35:.18)){let ps=state.roster.filter(p=>p.starter&&!p.injury),p=ps[ri(0,ps.length-1)];if(p){p.injury=ri(1,3);news('Medical room update',p.name+' is sidelined for '+p.injury+' week(s). His absence reduces starter strength.')}}if(state.week===17){let afc=rank(Array.from({length:16},(_,i)=>i)).slice(0,4),nfc=rank(Array.from({length:16},(_,i)=>i+16)).slice(0,4);state.playoffs={rounds:[[afc,nfc].flatMap(c=>[{a:c[0],b:c[3],score:null},{a:c[1],b:c[2],score:null}])]};state.phase='playoffs';news('The postseason is set',[...afc,...nfc].includes(state.team)?'You qualified for the playoffs. Time to finish the job.':'Your season is over. Watch the postseason and prepare for the draft.')}}else{let winners=gs.map(g=>g.score[0]>g.score[1]?g.a:g.b);if(winners.length===1){state.phase='offseason';news(cname(winners[0])+' are champions','The championship is decided. The draft is now open — make your three picks.');state.history.push({year:state.year,champion:winners[0],record:rec(state.team)})}else state.playoffs.rounds.push(Array.from({length:winners.length/2},(_,i)=>({a:winners[i*2],b:winners[i*2+1],score:null})))}if(report){let k=report.a===state.team?0:1,win=report.score[k]>report.score[1-k],o=k===0?report.b:report.a;state.morale=Math.max(35,Math.min(99,state.morale+(win?4:-5)));news(win?'A statement on the field':'Back to the drawing board',clubs[state.team][2]+' '+(win?'defeat':'fall to')+' the '+clubs[o][2]+', '+report.score[k]+'–'+report.score[1-k]+'.');render();showResult(report)}else{render();toast(state.phase==='offseason'?'Championship complete. The draft is open.':'Playoff round complete.')}}
function showResult(g){let k=g.a===state.team?0:1,o=k===0?g.b:g.a,win=g.score[k]>g.score[1-k];modal(`<div class="eyebrow">FULL TIME · ${win?'VICTORY':'DEFEAT'}</div><h2 style="margin-top:12px">${win?'A win for the franchise.':'On to the next one.'}</h2><div class="matchup"><b>${clubs[state.team][0]}</b><div class="score">${g.score[k]} – ${g.score[1-k]}</div><b>${clubs[o][0]}</b></div><p>${state.plan.offense} offense / ${state.plan.defense}. Your lineup, scheme fit, morale, home field and random game-day variation shaped this result.</p><div class="kv"><span>Season record</span><b>${rec(state.team)}</b></div><div class="kv"><span>Locker room morale</span><b>${state.morale}%</b></div><div class="modal-actions"><button class="secondary" onclick="closeModal();go('Schedule')">View schedule</button><button onclick="closeModal()">Back to the office →</button></div>`)}
function nextSeason(){let old=state,roster=old.roster.map(p=>({...p,age:p.age+1,injury:0,ovr:Math.max(55,Math.min(p.pot,p.ovr+(p.age<27?1:p.age>30?-2:0)))}));state=fresh(old.team,old.year+1,roster);state.history=old.history;closeModal();view='Overview';render();toast('Welcome to the '+state.year+' season')}
function modal(html){let m=document.getElementById('modal');m.innerHTML=html;if(!m.open)m.showModal()}function closeModal(){document.getElementById('modal').close()}function chooseClub(){modal(`<h2>Your franchise. Your legacy.</h2><p>Select a team to start a fresh career. This replaces your current browser save.</p><div class="club-grid">${clubs.map((c,i)=>`<button onclick="startCareer(${i})"><b>${c[0]}</b><br>${c[2]}</button>`).join('')}</div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Keep current career</button></div>`)}function startCareer(i){state=fresh(i);league=clubs[i][3];view='Overview';closeModal();render();toast('Welcome to the '+clubs[i][2]+' front office')}function showHelp(){modal(`<h2>Welcome to the front office.</h2><p><b>1. Build your roster.</b> Start with Dallas or choose another franchise. Sign free agents and promote reserves to improve your starters.</p><p><b>2. Set your identity.</b> Choose offensive and defensive schemes that suit your personnel. Training develops young players or helps injured players recover.</p><p><b>3. Play the season.</b> Advance a week to simulate all 16 matchups. Chase nine wins and a top-four conference finish.</p><p><b>4. Build a dynasty.</b> An eight-team playoff crowns a champion. Draft up to three rookies, then start the next year with your roster.</p><p>This is an independent, simplified prototype with fictional players and finances, a 17-week schedule without byes, and browser-local saving. No affiliation with the NFL or Football Manager.</p><div class="modal-actions"><button class="secondary" onclick="chooseClub()">Choose franchise</button><button onclick="closeModal()">Let's play →</button></div>`)}
render();
